"""Ground-plane geometry: distance, line of sight, collision slide, and a spatial grid."""

import math
from collections import defaultdict
from collections.abc import Iterable

from solo_engine.model import Rect


def distance(ax: float, ay: float, bx: float, by: float) -> float:
    return math.hypot(bx - ax, by - ay)


def normalize(x: float, y: float) -> tuple[float, float]:
    length = math.hypot(x, y)
    if length < 1e-9:
        return 0.0, 0.0
    return x / length, y / length


def clamp_to_map(x: float, y: float, size: float) -> tuple[float, float]:
    return min(max(x, 0.0), size), min(max(y, 0.0), size)


def inside_any(x: float, y: float, rects: Iterable[Rect]) -> bool:
    return any(rect.contains(x, y) for rect in rects)


def segment_hits_rect(ax: float, ay: float, bx: float, by: float, rect: Rect) -> bool:
    """Liang-Barsky clip: True when the segment a->b touches the rectangle."""
    dx = bx - ax
    dy = by - ay
    t0, t1 = 0.0, 1.0
    for p, q in ((-dx, ax - rect.min_x), (dx, rect.max_x - ax), (-dy, ay - rect.min_y), (dy, rect.max_y - ay)):
        if abs(p) < 1e-12:
            if q < 0:
                return False
            continue
        r = q / p
        if p < 0:
            if r > t1:
                return False
            t0 = max(t0, r)
        else:
            if r < t0:
                return False
            t1 = min(t1, r)
    return t0 <= t1


def line_of_sight(ax: float, ay: float, bx: float, by: float, blockers: Iterable[Rect]) -> bool:
    """True when no blocker lies between the two points. Shots and perception both use this."""
    return not any(segment_hits_rect(ax, ay, bx, by, rect) for rect in blockers)


def slide(x: float, y: float, nx: float, ny: float, blockers: Iterable[Rect]) -> tuple[float, float]:
    """Move to (nx, ny) unless a blocker is there; then try each axis alone; else stay."""
    blockers = tuple(blockers)
    if not inside_any(nx, ny, blockers):
        return nx, ny
    if not inside_any(nx, y, blockers):
        return nx, y
    if not inside_any(x, ny, blockers):
        return x, ny
    return x, y


class SpatialGrid:
    """Uniform grid of ids by cell. Rebuilt or updated each tick; queries are by radius."""

    def __init__(self, cell_size: float = 50.0) -> None:
        self.cell_size = cell_size
        self._cells: dict[tuple[int, int], set[str]] = defaultdict(set)
        self._where: dict[str, tuple[int, int]] = {}

    def _cell(self, x: float, y: float) -> tuple[int, int]:
        return int(x // self.cell_size), int(y // self.cell_size)

    def clear(self) -> None:
        self._cells.clear()
        self._where.clear()

    def update(self, item_id: str, x: float, y: float) -> None:
        cell = self._cell(x, y)
        old = self._where.get(item_id)
        if old == cell:
            return
        if old is not None:
            self._cells[old].discard(item_id)
        self._cells[cell].add(item_id)
        self._where[item_id] = cell

    def remove(self, item_id: str) -> None:
        old = self._where.pop(item_id, None)
        if old is not None:
            self._cells[old].discard(item_id)

    def near(self, x: float, y: float, radius: float) -> set[str]:
        """Ids in cells overlapping the square around (x, y). Callers filter by exact distance."""
        cx0, cy0 = self._cell(x - radius, y - radius)
        cx1, cy1 = self._cell(x + radius, y + radius)
        found: set[str] = set()
        for cx in range(cx0, cx1 + 1):
            for cy in range(cy0, cy1 + 1):
                found |= self._cells.get((cx, cy), set())
        return found
